import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav className="bg-blue-600 text-white p-4">
      <div className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-2xl font-bold">ApartmentFinder</Link>
        <div className="space-x-4">
          <Link to="/properties" className="hover:underline">Properties</Link>
          <Link to="/properties/new" className="bg-white text-blue-600 px-4 py-2 rounded hover:bg-blue-100">
            Add Property
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
